alignements = [[1, 2, 3], [4, 5, 6], [7, 8, 9], [1, 4, 7], [2, 5, 8],
               [3, 6, 9], [1, 5, 9], [3, 5, 7]]

def placements():
    L = []
    for i in range(1, 10):
        for j in range(i + 1, 10):
            for k in range(j + 1, 10):
                L.append([i, j, k])
    return L

def nombre_gagnants():
    compteur = 0
    for p in placements():
        if p in alignements:  # vrai si la liste p figure dans alignements
            compteur = compteur + 1
    return compteur

def seuil(s):
    n = 1
    while 1 - (15/16)**n < s:
        n = n + 1
    return n
